using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor{
[InitializeOnLoad]public static class RepairPointVerification{
 const string Key="RepairPointVerification";static double start;static List<string> rows=new List<string>();
 static RepairPointVerification(){if(SessionState.GetBool(Key,false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);rows.Add("PASS "+m);Debug.Log("REPAIR_PASS "+m);}
 static void Near(float a,float b,string m){Check(Mathf.Abs(a-b)<.001f,m+" "+a+" = "+b);}
 static bool Button(CampaignHUD h,string text){return h.GetComponentsInChildren<UnityEngine.UI.Button>(true).Any(b=>b.gameObject.activeInHierarchy&&b.GetComponentInChildren<Text>()!=null&&b.GetComponentInChildren<Text>().text.StartsWith(text));}
 static void Test(BattleWorld w){w.enabled=false;foreach(var initial in w.units)if(initial!=null&&initial.Point!=null)initial.BeginExit();w.GetComponent<BattleAIController>().enabled=false;w.GetComponent<AIBasicCommander>().enabled=false;w.fogEnabled=false;w.SetPlayer("A");foreach(var u in w.units){u.Motor.Stop();u.transform.position=new Vector3(u.ownerId=="A"?-44:44,-27);}Check(typeof(BattleUnit).Assembly.GetType("CampaignDemo.ResourceCollector")==null&&typeof(BattleUnit).Assembly.GetType("CampaignDemo.ResourceCollectorSettings")==null,"collector component and settings physically removed");Check(typeof(BattleUnit).Assembly.GetType("CampaignDemo.LogisticsHUD")==null,"old collector logistics UI physically removed");
 var units=w.units.Where(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry).ToArray();var a=units[0];var b=units[1];var city=w.points.First(p=>p.ownerId=="A");city.resourceStock=10000;var queue=FacilityRecoveryQueue.For(w);a.SetPersonnelExact(a.Capacity*.5f);b.SetPersonnelExact(b.Capacity*.5f);Check(a.BeginEnter(city)&&b.BeginEnter(city),"both units enter city immediately");Check(queue.Enqueue(a)&&queue.Enqueue(b)&&queue.Position(a)==1&&queue.Position(b)==2,"city FIFO queue follows request order");float pa=a.Personnel,pb=b.Personnel,stock=city.resourceStock;w.Tick(1);Near(a.Personnel-pa,a.Capacity*city.repairFractionPerSecond,"first city unit recovers");Near(b.Personnel,pb,"second city unit waits");Near(stock-city.resourceStock,a.Personnel-pa,"city recovery deducts actual resources");Check(queue.Toggle(a)&&!queue.Contains(a),"cancel removes current recovery");w.Tick(1);Check(b.Personnel>pb&&a.Personnel< a.Capacity,"next unit begins after cancellation");Check(b.BeginExit()&&!queue.Contains(b)&&b.OnMap,"leaving removes queued unit without delay");
 var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();hud.SelectUnit(a);Check(Button(hud,"恢复单位")&&Button(hud,"离开"),"inside city unit has recovery and leave buttons");hud.SelectBuilding(city);Check(Button(hud,"恢复单位")&&Button(hud,"离开"),"city garrison panel has recovery and leave buttons");a.BeginExit();
 var enemy=w.units.First(u=>u.ownerId=="B");w.NotifyUnitHit(enemy,"B",a);a.UnderFire=false;var position=city.transform.position+Vector3.up*.2f;var depot=w.campaign.CreateDepot(position,"A",0,false);Check(depot.displayName=="修复点"&&depot.recovery!=null&&depot.recovery.isRepairSite,"deployed warehouse becomes named repair point");Check(w.points.Contains(depot.recovery)&&depot.recovery.capacity==6,"repair point registered with six waiting places");a.transform.position=position;b.transform.position=position;a.SetPersonnelExact(a.Capacity*.5f);b.SetPersonnelExact(b.Capacity*.5f);hud.SelectUnit(a);Check(w.GetComponent<UnitContextOrders>().QueueEntry(a,depot.recovery,null)&&a.Point==depot.recovery,"map click can enter deployed repair point");Check(queue.Contains(a),"repair point entry automatically joins recovery queue");hud.SelectUnit(b);Check(w.GetComponent<UnitContextOrders>().QueueEntry(b,depot.recovery,null)&&queue.Position(b)==2,"second entrant waits behind first");pa=a.Personnel;pb=b.Personnel;stock=city.resourceStock;w.Tick(1);Check(a.Personnel>pa&&b.Personnel==pb,"repair point heals only queue head");Near(stock-city.resourceStock,a.Personnel-pa,"empty repair point uses nearest own city supplies");Check(depot.stock==0,"city supplies do not create phantom local stock");
 hud.SelectUnit(b);Check(Button(hud,"恢复单位")&&Button(hud,"离开"),"inside repair point unit has recovery and leave buttons");hud.SelectBuilding(depot);Check(Button(hud,"取消恢复")&&Button(hud,"离开"),"repair point panel exposes queued recovery cancellation and leave");Check(!Button(hud,"升级兵工厂")&&!Button(hud,"加入生产"),"repair point exposes no factory or unit production");var manager=w.GetComponent<CityManagement>();Check(!manager.Upgrade(depot.recovery,"A").allowed&&!manager.Truck(depot.recovery,"A",ArmyEchelon.Company).allowed,"repair point production blocked by game rules");Check(!w.GetComponent<InfantryProduction>().Quote("A",depot.recovery,ArmyEchelon.Squad).allowed,"repair point rejects direct production commands too");
 for(int i=0;i<110;i++)w.Tick(1);Check(a.Fraction>=.999999f&&b.Fraction>=.999999f&&!queue.Contains(a)&&!queue.Contains(b),"both entrants eventually recover fully in sequence");Check(UnitExperience.Ensure(a).Level==1,"full repair point recovery completes earned promotion");depot.stock=7;Near(depot.recovery.resourceStock,7,"depot stock and recovery stock share state");depot.recovery.resourceStock=9;Near(depot.stock,9,"recovery stock changes visible through depot");var point=depot.recovery;Check(w.campaign.RemoveDepot("A",depot).accepted,"repair point can be dismantled");Check(!w.points.Contains(point)&&a.OnMap&&b.OnMap&&a.Point==null&&b.Point==null,"dismantling evacuates occupants and removes ghost entry point");Check(w.campaign.depots.Any(d=>d!=depot&&d.resourcePile&&Mathf.Abs(d.stock-9)<.001f),"remaining stock preserved as resource pile");var pile=w.campaign.depots.First(d=>d!=depot&&d.resourcePile&&Mathf.Abs(d.stock-9)<.001f);var truck=w.units.First(u=>u.ownerId=="A"&&u.GetComponent<TransportTruck>()!=null).GetComponent<TransportTruck>();truck.Unit.Motor.Stop();truck.Unit.transform.position=pile.transform.position;truck.SetCargo(0);w.GetComponent<LocalPrototypeOrders>().Tick(.1f);Near(truck.Cargo,9,"truck can recover dismantled repair point stock");Check(pile.Removed,"empty resource pile disappears after pickup");
 var artillery=w.units.First(u=>u.ownerId=="A"&&u.GetComponent<ArtilleryBattery>()!=null);artillery.transform.position=city.transform.position+Vector3.right*2;Check(UnitRanges.Attack(artillery)>=8&&UnitRanges.Interaction(artillery)<1&&!w.CanEnter(artillery,city),"artillery firing range no longer enables remote city entry");Near(w.GetComponent<BattleInformationSource>().GetArmy("A",artillery.unitId).attackRadius.Value,UnitRanges.Attack(artillery),"information API reports real artillery range");
 int missing=0;foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);Check(missing==0,"current scene has no missing scripts after real deletion");
 }
 static void Poll(){try{if(EditorApplication.timeSinceStartup-start>120)throw new Exception("timeout");if(!EditorApplication.isPlaying||Time.time<.7f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;Test(w);Finish(null);}catch(Exception e){Finish(e);}}
 static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllText("C:/Users/ZWQ/Documents/Codex/2026-10-19/c-desktop-wargame-9/work/collector-repair-20261020/verification.txt",string.Join("\n",rows));SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
}}
